WITH sales_union AS ( SELECT ss_sold_date_sk AS sold_date_sk, ss_net_profit AS net_profit FROM store_sales UNION ALL SELECT ws_sold_date_sk AS sold_date_sk, ws_net_profit AS net_profit FROM web_sales ), daily_agg AS ( SELECT sold_date_sk, SUM(net_profit) AS total_net_profit FROM sales_union GROUP BY sold_date_sk ) SELECT d.d_date, d.d_day_name, CASE WHEN d.d_holiday = 'Y' THEN 1 ELSE 0 END AS is_holiday, CASE WHEN d.d_weekend = 'Y' THEN 1 ELSE 0 END AS is_weekend, da.total_net_profit, SUM(da.total_net_profit) OVER (ORDER BY d.d_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_net_profit, RANK() OVER (ORDER BY da.total_net_profit DESC) AS profit_day_rank FROM daily_agg da JOIN date_dim d ON da.sold_date_sk = d.d_date_sk ORDER BY d.d_date LIMIT 365
